import{_ as a,o,c as n,ae as t}from"./chunks/framework.Co1PSFSm.js";const m=JSON.parse('{"title":"Análisis y Funciones Obsoletas","description":"","frontmatter":{},"headers":[],"relativePath":"reference/analisis.md","filePath":"reference/analisis.md"}'),i={name:"reference/analisis.md"};function r(s,e,l,d,c,u){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="analisis-y-funciones-obsoletas" tabindex="-1">Análisis y Funciones Obsoletas <a class="header-anchor" href="#analisis-y-funciones-obsoletas" aria-label="Permalink to &quot;Análisis y Funciones Obsoletas&quot;">​</a></h1><p>Este documento mantiene un registro de las funciones deprecadas o planificadas que pueden figurar en documentación muy antigua, y su estado actual en la <strong>V14.1.0</strong>.</p><h2 id="_1-identidad-del-agente" tabindex="-1">1. Identidad del Agente <a class="header-anchor" href="#_1-identidad-del-agente" aria-label="Permalink to &quot;1. Identidad del Agente&quot;">​</a></h2><ul><li><strong>Obsoleto:</strong> El uso de un archivo estático <code>/host_root/etc/dbp_agent_id</code> introducido en V2.4.</li><li><strong>Actual:</strong> <code>Fingerprint</code> (Huella digital híbrida calculada en tiempo de ejecución) desde V13.</li></ul><h2 id="_2-restic-check-verificacion-de-integridad" tabindex="-1">2. Restic Check (Verificación de Integridad) <a class="header-anchor" href="#_2-restic-check-verificacion-de-integridad" aria-label="Permalink to &quot;2. Restic Check (Verificación de Integridad)&quot;">​</a></h2><ul><li><strong>Obsoleto:</strong> Lanzar <code>restic check</code> manualmente o solo al arranque del agente.</li><li><strong>Actual:</strong> El motor de Go lo ejecuta automáticamente al terminar un backup (<code>RunResticVerify()</code>) y reporta &quot;VALID&quot; o &quot;INVALID&quot; inmediatamente.</li></ul><h2 id="_3-modo-rescue-v2-inyeccion-ssh" tabindex="-1">3. Modo Rescue V2 (Inyección SSH) <a class="header-anchor" href="#_3-modo-rescue-v2-inyeccion-ssh" aria-label="Permalink to &quot;3. Modo Rescue V2 (Inyección SSH)&quot;">​</a></h2><ul><li><strong>Concepto:</strong> Utilizaba un script para inyectar comandos vía SSH en un servidor bare-metal nuevo y restaurar directamente.</li><li><strong>Estado:</strong> Pospuesto/Interno. Interfiere con el modelo de responsabilidades Zero-Config. El flujo actual preferido es instalar el Agente V14 usando el comando <code>curl</code> estándar, y luego usar el Restore Wizard.</li></ul><h2 id="_4-work-in-progress-cuellos-de-botella" tabindex="-1">4. Work in Progress (Cuellos de Botella) <a class="header-anchor" href="#_4-work-in-progress-cuellos-de-botella" aria-label="Permalink to &quot;4. Work in Progress (Cuellos de Botella)&quot;">​</a></h2><ul><li><strong>Asynchronous Job Worker:</strong> Aún se depende de concurrencia nativa (Goroutines) para guardar Heartbeats. Planeado migrar a colas de mensajería (RabbitMQ/Redis Streams) para soportar más de 1000 agentes simultáneos.</li><li><strong>Post-Restore Validation:</strong> Falta la validación empírica en el servidor destino (ej. ping al puerto del contenedor) tras un <code>restic restore</code>. Actualmente solo se valida que el binario de Restic no falló.</li></ul>',10)])])}const h=a(i,[["render",r]]);export{m as __pageData,h as default};
